// Example 1: Mixed Precedence (L-to-R Grouping)
// Precedence Order: *, <<, &
// Evaluation: ((A * B) << C) & D
int A = 2, B = 3, C = 1, D = 4;
int result = A * B << C & D; // 6 << 1 = 12, then 12 & 4 = 4

// Example 2: Right-to-Left Associativity (Assignment)
int i, j, k;
i = j = k = 10; // Evaluated R-to-L: (k=10), then (j=k), then (i=j)

// Example 3: Right-to-Left Associativity (Ternary/Conditional)
int val = (k > 5) ? 1 : (j > 5) ? 2 : 3;
// Grouping: (k > 5) ? 1 : ( (j > 5) ? 2 : 3 )

// Example 4: Postfix vs Prefix Unary Operators
int arr[] = {10, 20};
int *p = arr;

// Postfix '++' binds tighter than prefix '*'
int v1 = *p++;   // Evaluates *(p++), v1=10, p moves to arr[1]

// Prefix '++' is same precedence as '*' (R-to-L)
int v2 = *++p;   // Evaluates *(++p), p moves to arr[1] (if reset), v2=20 (if p reset)
